// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actorA, address actorB, uint256 vA1, uint256 vA2, uint256 vB) public {
        vm.assume(actorA != actorB);
        vm.assume(actorA != address(0) && actorB != address(0));
        vA1 = bound(vA1, 1, type(uint128).max);
        vA2 = bound(vA2, 1, type(uint128).max);
        vB  = bound(vB, 1, type(uint128).max);

        vm.deal(actorA, vA1);
        vm.prank(actorA);
        c.addToBalance{value: vA1}();

        vm.deal(actorA, vA2);
        vm.prank(actorA);
        c.addToBalance{value: vA2}();

        vm.deal(actorB, vB);
        vm.prank(actorB);
        c.addToBalance{value: vB}();

        uint256 balA = c.getBalance(actorA);
        assertTrue(balA == vA1 + vA2);
    }
}
